-- Additive vSRO item catalog. RAW_DATA preserves every source column while
-- typed keys support joins without changing the live ITEMDATA table.
CREATE TABLE `REF_OBJ_COMMON_VSRO` (`ID` INT NOT NULL, `SERVICE` TINYINT UNSIGNED NOT NULL, `CODE_NAME` VARCHAR(128) NOT NULL, `TYPE_ID_1` TINYINT UNSIGNED NOT NULL, `TYPE_ID_2` TINYINT UNSIGNED NOT NULL, `TYPE_ID_3` TINYINT UNSIGNED NOT NULL, `TYPE_ID_4` TINYINT UNSIGNED NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`ID`), KEY `idx_ref_obj_common_vsro_code` (`CODE_NAME`)) ENGINE=InnoDB;
CREATE TABLE `REF_OBJ_ITEM_VSRO` (`ID` INT NOT NULL, `SET_ID` INT NOT NULL, `ITEM_CLASS` TINYINT UNSIGNED NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`ID`), KEY `idx_ref_obj_item_vsro_set` (`SET_ID`), CONSTRAINT `fk_ref_obj_item_vsro_common` FOREIGN KEY (`ID`) REFERENCES `REF_OBJ_COMMON_VSRO` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_OBJ_STRUCT_VSRO` (`ID` INT NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`ID`), CONSTRAINT `fk_ref_obj_struct_vsro_common` FOREIGN KEY (`ID`) REFERENCES `REF_OBJ_COMMON_VSRO` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_PACKAGE_ITEM_VSRO` (`COUNTRY` INT NOT NULL, `ID` INT NOT NULL, `CODE_NAME` VARCHAR(128) NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`COUNTRY`,`ID`), KEY `idx_ref_package_item_vsro_code` (`CODE_NAME`)) ENGINE=InnoDB;
CREATE TABLE `REF_PRICE_POLICY_ITEM_VSRO` (`COUNTRY` INT NOT NULL, `PACKAGE_CODE_NAME` VARCHAR(128) NOT NULL, `PAYMENT_DEVICE` INT NOT NULL, `RAW_DATA` JSON NOT NULL, KEY `idx_ref_price_policy_item_vsro_package` (`COUNTRY`,`PACKAGE_CODE_NAME`)) ENGINE=InnoDB;
CREATE TABLE `REF_ABILITY_ITEM_OPT_LEVEL_VSRO` (`ID` INT NOT NULL, `REF_ITEM_ID` INT NOT NULL, `ITEM_OPT_LEVEL` TINYINT UNSIGNED NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`ID`), KEY `idx_ref_ability_item_opt_level_vsro_item` (`REF_ITEM_ID`), CONSTRAINT `fk_ref_ability_item_opt_level_vsro_item` FOREIGN KEY (`REF_ITEM_ID`) REFERENCES `REF_OBJ_COMMON_VSRO` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_MAGIC_OPT_ITEM_OPT_LEVEL_VSRO` (`LINK` INT NOT NULL, `REF_MAGIC_OPT_ID` SMALLINT NOT NULL, `RAW_DATA` JSON NOT NULL, KEY `idx_ref_magic_opt_item_opt_level_vsro_link` (`LINK`), CONSTRAINT `fk_ref_magic_opt_item_opt_level_vsro_ability` FOREIGN KEY (`LINK`) REFERENCES `REF_ABILITY_ITEM_OPT_LEVEL_VSRO` (`ID`)) ENGINE=InnoDB;
CREATE TABLE `REF_SET_ITEM_GROUP_VSRO` (`ID` INT NOT NULL, `CODE_NAME` VARCHAR(128) NOT NULL, `RAW_DATA` JSON NOT NULL, PRIMARY KEY (`ID`)) ENGINE=InnoDB;
